-- This test-only SQL exercises DDL contracts, not production query behavior.
SET LOCAL app.tenant_bypass = 'true';
CREATE FUNCTION pg_temp.expect_error(statement text, expected_state text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
    BEGIN
        EXECUTE statement;
    EXCEPTION WHEN OTHERS THEN
        IF SQLSTATE = expected_state THEN RETURN; END IF;
        RAISE;
    END;
    RAISE EXCEPTION 'expected SQLSTATE %, query succeeded: %', expected_state, statement;
END;
$$;

